"""Generate the downloadable project brief. Run with Python and Playwright installed."""
from pathlib import Path
from playwright.sync_api import sync_playwright
from base64 import b64encode

root = Path(__file__).resolve().parents[1]
image = b64encode((root / 'public/images/energy-valley-small.webp').read_bytes()).decode()
font = b64encode((root / 'public/fonts/manrope-variable.ttf').read_bytes()).decode()
css = '''@page {size:A4;margin:0} *{box-sizing:border-box} body{margin:0;font:11px/1.65 Manrope,Arial,sans-serif;color:#243a2a} .sheet{height:296.9mm;position:relative;padding:15mm 17mm;break-after:page} .sheet:last-child{break-after:auto}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #bdcdb7;padding-bottom:11px;font-weight:700;letter-spacing:1.6px;font-size:10px}.top small{color:#708069;font-size:8px}.label{display:block;color:#658358;font-weight:700;font-size:8px;letter-spacing:2px;text-transform:uppercase;margin:24px 0 10px}h1{font-size:39px;font-weight:550;letter-spacing:-2.3px;line-height:1.07;margin:16px 0}h2{font-size:26px;line-height:1.15;letter-spacing:-1.4px;font-weight:550;margin:15px 0}h3{font-size:15px;font-weight:650;letter-spacing:-.5px;margin:15px 0 4px}p{margin:0 0 9px}.cover{width:100%;height:180px;object-fit:cover;object-position:center 63%;border-radius:6px;margin:12px 0}.muted{color:#60725a}.rule{border-top:1px solid #dce4d7;padding-top:8px;margin-top:12px}.banner{padding:14px 17px;background:#eaf0e4;border-left:3px solid #6e905f;margin:18px 0;color:#405b37}.footer{position:absolute;bottom:12mm;left:17mm;right:17mm;border-top:1px solid #cad8c3;padding-top:9px;display:flex;justify-content:space-between;font-size:8px;color:#6b7d63;letter-spacing:.6px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:23px}.step{display:grid;grid-template-columns:28px 90px 1fr;gap:8px;border-top:1px solid #dce4d6;padding:11px 0}.step span{color:#82977a}.step b{font-size:12px}.step p{margin:0}.flow{background:#173c2f;color:#edf4e7;padding:15px;border-radius:6px;font-size:12px}.tag{font-size:8px;color:#66825a;font-weight:700;letter-spacing:1.3px}'''
css += f"@font-face{{font-family:Manrope;src:url(data:font/ttf;base64,{font}) format('truetype');font-weight:200 800}}"
def header(n): return '<div class="top"><span>ORAYAH DYNAMIS</span><small>PROJECT BRIEF &nbsp; / &nbsp; '+n+'</small></div>'
def footer(n): return '<div class="footer"><span>THE COMMUNITY ENERGY ECOSYSTEM</span><span>PROPOSED SYSTEM DESIGN &nbsp; / &nbsp; '+n+'</span></div>'
a = header('01') + f'''<span class="label">Project overview</span><h1>Local energy.<br>Collective power.</h1><p class="muted">ORAYAH DYNAMIS — The Community Energy Ecosystem</p><img class="cover" src="data:image/webp;base64,{image}"><h2>The community energy concept.</h2><p>ORAYAH is a proposed decentralized smart energy ecosystem that brings renewable generation, managed battery storage, and intelligent energy management together through a common DC microgrid.</p><div class="pair"><div><h3>The challenge</h3><p>Solar availability and energy demand are not always aligned. Unreliable grid supply can expose essential community services to interruption and increase reliance on diesel backup.</p></div><div><h3>The proposed solution</h3><p>Capture local solar power, store surplus generation, and coordinate consumption through forecasts, adaptive schedules, and community-defined priorities.</p></div></div><div class="banner"><b>Scope and status</b><br>This brief describes a system concept and proposed initial prototype. It does not claim deployed installations, verified efficiency, achieved reliability, or measured community outcomes. Imagery is illustrative.</div><h3>Three connected divisions</h3><p><b>LUMEN</b> — renewable generation and power conditioning.<br><b>TAMID</b> — managed battery storage and protection.<br><b>GRID</b> — supervisory intelligence, monitoring, and scheduling.</p>''' + footer('01 / 03')
b = header('02') + '''<span class="label">Technical architecture</span><h1>Inside the microgrid.</h1><p class="muted">Power paths, monitoring signals, and logical control commands serve different functions.</p><div class="flow">Solar PV → boost converter → common 400V DC bus<br>DC bus ↔ proposed bidirectional interface ↔ battery + BMS</div><h3>01 / ORAYAH LUMEN</h3><p>Photovoltaic modules generate DC electricity. Perturb and Observe maximum power point tracking adjusts the converter operating point to seek available PV power. The boost converter conditions the voltage for the proposed common bus. MPPT is a control algorithm, not an energy-transfer component.</p><h3>02 / ORAYAH TAMID</h3><p>Initial storage uses batteries with a battery management system, monitoring, protection, State of Charge estimation, and State of Health estimation. A suitably rated, managed bidirectional interface is required for charging and discharging on the shared bus.</p><div class="banner"><b>Future research—not part of the initial prototype</b><br>Gravity-based storage and Phase Change Material (PCM) thermal storage are future integration concepts. PCM stores thermal energy; it is not shown as an electrical battery on the DC bus.</div><h3>03 / ORAYAH GRID</h3><p>The proposed Intelligent Energy Management System (IEMS) uses measurements and forecasts to schedule generation use, storage, and demand. Potential functions include adaptive scheduling, AI-assisted demand response, priority-based allocation, energy monitoring, and fault detection.</p><h3>Measurement and control</h3><p>ESP32-based monitoring obtains voltage, current, temperature, and power data through suitable isolated or conditioned sensing interfaces. Telemetry informs the IEMS; logical control requests go to validated local controllers. Hardware protection remains independent of AI decisions.</p><h3>Proposed distribution</h3><p>A single-phase inverter provides a proposed 230V AC distribution branch. A regulated step-down DC–DC stage is required for proposed 48V DC distribution. Compatible community loads are allocated according to agreed priorities.</p><div class="rule"><b>Engineering boundary.</b> 400V DC, 230V AC, and 48V DC are design targets, not measured outputs. Converter topology, component ratings, isolation, earthing, protection, switching interfaces, and safe operating limits require detailed engineering and validation.</div>''' + footer('02 / 03')
steps=[('Generate','PV panels convert locally available sunlight into DC electricity.'),('Optimize','P&O MPPT seeks available solar power through converter control.'),('Store','Managed battery charging saves surplus generation for later demand.'),('Monitor','Conditioned ESP32 sensing collects electrical and temperature measurements.'),('Predict','The proposed IEMS evaluates expected power availability and demand.'),('Manage','Adaptive scheduling coordinates storage use and flexible consumption.'),('Prioritize','Community-defined rules give essential circuits priority during shortages.')]
c = header('03') + '<span class="label">Operation & intended impact</span><h1>From sunlight to service.</h1>' + ''.join(f'<div class="step"><span>0{i+1}</span><b>{k}</b><p>{v}</p></div>' for i,(k,v) in enumerate(steps)) + '''<h2>Community applications.</h2><p>Proposed applications include households, healthcare centres and clinics, schools, water pumping stations, small businesses, and shared essential services. During a limited-supply condition, critical care and essential water needs may take priority while flexible loads are shifted. Actual policies must be defined with each community.</p><h3>Intended benefits</h3><p>Better renewable energy utilization; reduced grid and diesel dependence; more informed energy management; and support for essential services. Modular, repairable design is intended to enable maintenance and expansion over time.</p><h3>Community ownership and sharing</h3><p>Community ownership and peer-to-peer energy sharing are longer-term possibilities. Governance, metering, settlement, regulation, and local consent must be addressed before any sharing arrangement is implemented.</p><div class="banner"><b>Validation comes next.</b> These are design intentions, not proven outcomes. Future prototype testing and community evaluation are needed to establish actual performance, safety, reliability, and impact.</div>''' + footer('03 / 03')
html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>ORAYAH DYNAMIS — Project brief</title><style>'+css+'</style></head><body>'+''.join('<section class="sheet">'+s+'</section>' for s in [a,b,c])+'</body></html>'
with sync_playwright() as p:
    browser = p.chromium.launch(args=['--no-sandbox'])
    page = browser.new_page()
    page.set_content(html, wait_until='load')
    page.evaluate('document.fonts.ready')
    page.pdf(path=str(root/'public/orayah-project-brief.pdf'), print_background=True, prefer_css_page_size=True, tagged=True)
    browser.close()
print('Created the ORAYAH project brief.')
